 function title(text){return titles[text]||text;}
 function sceneText(p){
  const texts={party:'Ника зовёт на вечеринку. Можно пойти к ней, заняться делом с Сашей или отдохнуть.',assessment:'Несколько месяцев обычные дела даются тяжело. Можно обратиться к специалисту.',treatment:'После оценки состояния специалист выявил депрессивный эпизод и предложил лечение.',review:'Состояние улучшилось. Специалист предлагает вместе пересмотреть план лечения.'};
  return texts[p.topic]||p.text;
 }
 function hint(s,p,o){
  if(p.kind==='social'){
   if(p.topic==='party'&&o.action==='party')return root.LifeHabits.recoveryHint(s);
   if(o.action==='corrupt')return 'Выгода сейчас; риск огласки и потери доверия.';
   if(o.action==='cover')return 'Доверие других людей может пострадать.';
   if(p.topic==='child'&&o.action==='ignore')return 'Ребёнок останется без вашей поддержки.';
   return '';
  }
  if(p.topic==='treatment'&&o.action==='combined')return 'Психотерапия и назначенные лекарства; возможны побочные эффекты.';
  if(p.topic==='treatment'&&o.action==='therapy')return 'Обсудить вариант без лекарств, с наблюдением.';
  if(p.topic==='review'&&o.action==='taper')return 'Постепенно, вместе со специалистом.';
  if(o.action==='use'&&p.topic==='unknown')return 'Состав и действие неизвестны.';
  if(o.action==='use'&&p.topic==='alcohol')return root.LifeHabits.recoveryHint(s).replace('На вечеринке','Сейчас');
  if(o.action==='use'&&(s.habits?.urges?.[p.topic]||0)>=30)return 'Сейчас тяга сильнее обычного.';
  return '';
 }
 function careerHint(p,o){
  if(o.disabled)return 'Сначала завершите подготовку.';
  const hints={parttime:'Меньше часов и дохода.',break:'Доход временно прекратится; опыт сохранится.',self:'Нужен резерв; доход будет переменным.',project:'Потребуются время и часть средств.',intern:'Небольшой доход; меньше свободного времени.'};
  if(hints[o.action])return hints[o.action];
  if(o.action==='field'&&p.topic!=='school'&&o.desc?.includes('длительная подготовка'))return 'Потребуется длительная подготовка.';
  return '';
 }
 function heading(p){return p.topic==='party'?'Планы на вечер':p.title;}
